add_action( 'template_redirect', 'perfectpixel_prefill_checkout_store' );
add_filter( 'woocommerce_checkout_get_value', 'perfectpixel_prefill_checkout_value', 10, 2 );

function perfectpixel_prefill_checkout_fields() {
	$fields = array();
	foreach ( array( 'first_name', 'last_name', 'company', 'address_1', 'address_2', 'city', 'postcode', 'country', 'state' ) as $name ) {
		$fields[] = 'billing_' . $name;
		$fields[] = 'shipping_' . $name;
	}
	$fields[] = 'billing_email';
	$fields[] = 'billing_phone';
	return $fields;
}

function perfectpixel_prefill_checkout_store() {
	if ( ! function_exists( 'is_checkout' ) || ! is_checkout() || ! WC()->session ) {
		return;
	}

	$data = (array) WC()->session->get( 'perfectpixel_prefill', array() );
	foreach ( perfectpixel_prefill_checkout_fields() as $key ) {
		if ( isset( $_GET[ $key ] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
			$value        = wp_unslash( $_GET[ $key ] ); // phpcs:ignore WordPress.Security.NonceVerification, WordPress.Security.ValidatedSanitizedInput
			$data[ $key ] = 'billing_email' === $key ? sanitize_email( $value ) : sanitize_text_field( $value );
		}
	}

	if ( $data ) {
		if ( ! WC()->session->has_session() ) {
			WC()->session->set_customer_session_cookie( true );
		}
		WC()->session->set( 'perfectpixel_prefill', $data );
	}
}

function perfectpixel_prefill_checkout_value( $value, $input ) {
	if ( function_exists( 'WC' ) && WC()->session ) {
		$data = (array) WC()->session->get( 'perfectpixel_prefill', array() );
		if ( isset( $data[ $input ] ) && '' !== $data[ $input ] ) {
			return $data[ $input ];
		}
	}
	return $value;
}
